const side=document.querySelector('.side');
const sideBackdrop=document.createElement('button');sideBackdrop.className='side-backdrop';sideBackdrop.type='button';sideBackdrop.setAttribute('aria-label','إغلاق القائمة');document.body.append(sideBackdrop);
function toggleSide(open){side?.classList.toggle('open',open);sideBackdrop.classList.toggle('show',open);document.body.classList.toggle('side-open',open);document.querySelectorAll('.mobile-toggle').forEach(b=>b.setAttribute('aria-expanded',String(open)))}
document.querySelectorAll('.mobile-toggle').forEach(b=>{b.setAttribute('aria-label','فتح القائمة');b.setAttribute('aria-expanded','false');b.onclick=()=>toggleSide(!side?.classList.contains('open'))});sideBackdrop.onclick=()=>toggleSide(false);document.addEventListener('keydown',e=>{if(e.key==='Escape')toggleSide(false)});
const memberTarget=href=>href==='#myNutrition'?'#dailyNutrition':href;
document.querySelectorAll('.side nav a[href^="#"],.bottom-nav a[href^="#"]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();const href=link.getAttribute('href'),target=document.querySelector(href)||document.querySelector(memberTarget(href));if(!target)return;document.querySelectorAll('.side nav a,.bottom-nav a').forEach(a=>a.classList.toggle('active',memberTarget(a.getAttribute('href'))===memberTarget(href)));toggleSide(false);target.scrollIntoView({behavior:'smooth',block:'start'});history.replaceState(null,'',href)}));
const toast=document.getElementById('actionToast');let toastTimer;
function notify(message,type='ok'){if(!toast)return;toast.textContent=message;toast.dataset.type=type;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3500)}
const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const date=value=>{if(!value)return'—';const raw=String(value),ymd=raw.match(/^(\d{4})-(\d{2})-(\d{2})/);if(ymd&&!raw.includes('T'))return`${Number(ymd[3])}/${Number(ymd[2])}/${ymd[1]}`;const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'—':`${parsed.getDate()}/${parsed.getMonth()+1}/${parsed.getFullYear()}`};
const statusLabel={pending:'بانتظار الموافقة',active:'نشط',blocked:'محظور',rejected:'مرفوض',awaiting_payment:'بانتظار الدفع',expired:'منتهي',cancelled:'ملغي'};
let adminStore=null,currentProfile=null,memberFilter='all',memberHealth=null,memberWorkoutLogs=[],memberMealLogs=[],currentMemberProgram=null,notificationItems=[];

function addNotificationCenter(){const top=document.querySelector('.top');if(!top)return;const bell=document.createElement('button');bell.className='notification-bell';bell.type='button';bell.innerHTML='<span>🔔</span><b>0</b>';bell.setAttribute('aria-label','التنبيهات');const panel=document.createElement('section');panel.className='notification-panel';panel.innerHTML='<header><strong>التنبيهات</strong><button type="button">تحديد الكل كمقروء</button></header><div class="loading">جاري التحميل…</div>';document.body.append(panel);top.querySelector('.top-actions')?.prepend(bell);bell.onclick=()=>panel.classList.toggle('open');document.addEventListener('click',e=>{if(!panel.contains(e.target)&&!bell.contains(e.target))panel.classList.remove('open')});panel.querySelector('header button').onclick=async()=>{const unread=notificationItems.filter(x=>!x.read_at);if(!unread.length)return;const button=panel.querySelector('header button');button.disabled=true;try{await Promise.all(unread.map(x=>StrongGymAPI.markNotificationRead(x.id)));notificationItems.forEach(x=>x.read_at=x.read_at||new Date().toISOString());panel.querySelectorAll('.unread').forEach(x=>x.classList.remove('unread'));bell.querySelector('b')?.remove();notify('تم تحديد كل التنبيهات كمقروءة')}catch(error){notify(error.message,'error')}finally{button.disabled=false}};return{bell,panel}}
const notificationUI=addNotificationCenter();
const topLogout=document.createElement('button');topLogout.type='button';topLogout.className='db-btn top-logout';topLogout.innerHTML='<span>خروج</span> ↪';topLogout.setAttribute('aria-label','تسجيل الخروج');document.querySelector('.top-actions')?.append(topLogout);
async function loadNotifications(){const notices=await StrongGymAPI.notifications().catch(()=>[]);notificationItems=notices;if(!notificationUI)return;const {bell,panel}=notificationUI;panel.querySelectorAll('article,.loading').forEach(x=>x.remove());notices.forEach(item=>{const row=document.createElement('article');if(!item.read_at)row.className='unread';row.innerHTML=`<i></i><div><b>${esc(item.title_ar)}</b><p>${esc(item.body_ar)}</p><small>${date(item.created_at)}</small></div>`;row.onclick=()=>{if(!item.read_at){StrongGymAPI.markNotificationRead(item.id);item.read_at=new Date().toISOString();row.classList.remove('unread')}};panel.append(row)});if(!notices.length)panel.insertAdjacentHTML('beforeend','<div class="empty-state">لا توجد تنبيهات.</div>');const count=notices.filter(x=>!x.read_at).length,badge=bell.querySelector('b');if(count)badge.textContent=count;else badge?.remove()}

function goView(name,push=true){const target=document.querySelector(`[data-view="${name}"]`);if(!target)return;document.querySelectorAll('.admin-view').forEach(v=>v.classList.toggle('active',v===target));document.querySelectorAll('[data-view-link]').forEach(a=>a.classList.toggle('active',a.dataset.viewLink===name));const titles={overview:'لوحة الإدارة',members:'إدارة المشتركين',payments:'الاشتراكات والدفعات',measurements:'سجل القياسات',plans:'التمارين والتغذية',settings:'الإعدادات'};document.getElementById('pageTitle').textContent=titles[name]||'لوحة الإدارة';if(push&&location.hash!==`#${name}`)history.pushState(null,'',`#${name}`);side?.classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-view-link],[data-go]').forEach(el=>el.onclick=e=>{e.preventDefault();goView(el.dataset.viewLink||el.dataset.go)});window.addEventListener('hashchange',()=>goView(location.hash.slice(1)||'overview',false));
